import re
import time
import taf.rfrl.cbts.utilities.artifactory as artifactory
from robot.api import logger
from taf.hw.fhgw.cli import cli
from taf.rfrl.cbts.connections.conn_netact import GenericNetAct


class NetactCLI(GenericNetAct):

    def __init__(self):
        self.masterip = None
        self.username = None
        self.password = None
        self.netactlink = None

    def _get_netact_username_password(self, netact_index=None):
        GenericNetAct.select_available_netact(self, netact_index)
        self.masterip = self.hostname
        self.username = self.ssh_username
        self.password = self.ssh_password
        self.netactlink = self.web_url

    def _get_lcmserver_ip_address(self):
        try:
            ssh_conn = cli()
            myprompt = r"\[omc@\S+\s\S+\]\$"
            ssh_conn.connect_to(self.masterip, self.username, self.password, prompt=myprompt)
            getlcmservercommand = "cat /etc/hosts |grep lcm |grep -E -o \"([0-9]{1,3}[\\.]){3}[0-9]{1,3}\""
            logger.info(getlcmservercommand)
            out = ssh_conn.execute(getlcmservercommand)
            logger.info('command return {0}'.format(out))
            out = out.replace('\r\n', '|')
            out = out.split('|')
            tempout = out[1]
            tempout = tempout.strip()
            lcmipaddresslist = re.findall(r'[0-9]+(?:\.[0-9]+){3}', tempout)
            logger.info('LCM server IP {0}'.format(lcmipaddresslist))
            return lcmipaddresslist[0]
        except Exception as e:
            logger.info("To get the LCM server IP error")
            logger.error(e)
        finally:
            ssh_conn.disconnect()
        return None

    def get_chart_name_by_swversion_from_lcmserver(self, swversion, netact_index=None):
        """
        Get chart name from netact LCM server
        the package version need upload to netact before getting the chart name

        _*Parameters:*_
        | Input Parameters | Man. | Description                                        |
        | swversion        | Yes  | product package version, vcu/vdu version           |
        | netact_index     | Yes  | netact select                                      |

        _*Return Value:*_
        | Return Value | Return three charts name, "cluster name, prerequisite name, main name" |

        _*Example:*_
        | ${swversion}     | "vDUCNF00_0.300.14035"                               |
        | ${netact_index}  | "None"                                       |                                           |
        | get_chart_name_by_swversion | ${swversion}  | ${netact_index} |

        """
        self._get_netact_username_password(netact_index)
        lcmserverip = self._get_lcmserver_ip_address()
        time.sleep(20)
        mainversion = swversion.split('_')[1]
        command = """ls /d/oss/global/var/swm/swm_arch/{0}/extracted/HelmChart | grep tgz"""
        command = command.format(swversion)
        logger.info(command)
        try:
            ssh_connlcm = cli()
            myprompt = r"\[omc@\S+\s\S+\]\$"
            ssh_connlcm.connect_to(ip=lcmserverip, username=self.username, password=self.password, prompt=myprompt)
            out = ssh_connlcm.execute(command=command)
            logger.info('command return {0}'.format(out))
            out = out.replace('\r\n', ',')
            if len(out) < 20:
                logger.info("Error: Helm Chart name can not be found in LCM server.")
                return "", "", ""
            outlist = out.split(',')
            for tempfile in outlist:
                file = tempfile.strip()
                if file.strip().find('cluster') > 0:
                    clusterpreparationfile = file
                elif file.strip().find('prerequisite') > 0:
                    prerequisitefile = file
                elif (file.strip().find(mainversion) > 0) and (file.strip().find('upgrade') < 0) and (file.strip().find('unlock') < 0):
                    mainfile = file
            printstring = """{0} chart name: {1},  {2},  {3}"""
            printstring = printstring.format(swversion, clusterpreparationfile, prerequisitefile, mainfile)
            logger.info(printstring)
        except Exception as e:
            logger.info("To get chart name error from LCM server")
            logger.info(e)
        finally:
            ssh_connlcm.disconnect()
        tempcluster = re.findall(r'aic-v[cd]u-cluster-preparation-[0-9]+(?:\.[0-9]+){2}', clusterpreparationfile)
        returncluster = tempcluster[0] + ".tgz"
        tempprerequisite = re.findall(r'aic-v[cd]u-prerequisite-[0-9]+(?:\.[0-9]+){2}', prerequisitefile)
        returnprerequisite = tempprerequisite[0] + ".tgz"
        tempmain = re.findall(r'aic-v[cd]u-[0-9]+(?:\.[0-9]+){2}', mainfile)
        returmain = tempmain[0] + ".tgz"
        return returncluster, returnprerequisite, returmain

    def download_swpackage_to_netact(self, swversion, netact_swm_path="/d/oss/global/swmanager/swm_temp",
                                     netact_index=None, artifactory_location="HZ"):
        artifactory_url = artifactory._get_artifactory_url_for_location(artifactory_location)
        self._get_netact_username_password(netact_index)
        lcmserverip = self._get_lcmserver_ip_address()
        time.sleep(20)
        myswversion = swversion.strip()
        versionstyle = myswversion.split('_')[0]
        token = artifactory._get_ute_token_from_file()
        command = (
            "cd {0}; wget --header='X-JFrog-Art-Api: {1}' "
            "{2}/artifactory/mnp5g-central-public-remote/System_Release/{3}/{4}/{5}.zip"
        )
        command = command.format(netact_swm_path, token, artifactory_url, versionstyle, myswversion, myswversion)
        logger.info(command)
        try:
            ssh_connlcm = cli()
            myprompt = r"\[omc@\S+\s\S+\]\$"
            ssh_connlcm.connect_to(ip=lcmserverip, username=self.username, password=self.password, prompt=myprompt)
            ssh_connlcm.set_timeout(600)
            out = ssh_connlcm.execute(command=command)
            logger.info('command return {0}'.format(out))
            return True
        except Exception as e:
            logger.error("To download SW to LCM server Error")
            logger.error(e)
        finally:
            ssh_connlcm.disconnect()
        return False

    def upload_pnpscfplan_to_netact(self, local_path, remote_path="/var/opt/oss/global/racops/import", netact_index=None):
        self._get_netact_username_password(netact_index)
        lcmserverip = self._get_lcmserver_ip_address()
        time.sleep(20)
        try:
            ssh_connlcm = cli()
            myprompt = r"\[omc@\S+\s\S+\]\$"
            ssh_connlcm.connect_to(ip=lcmserverip, username=self.username, password=self.password, prompt=myprompt)
            ssh_connlcm.set_timeout(600)
            out = ssh_connlcm.upload_file(local_path=local_path, remote_path=remote_path)
            logger.info('upload file return {0}'.format(out))
            return True
        except Exception as e:
            logger.error("To upload pnpscfplan to LCM server Error")
            logger.error(e)
        finally:
            ssh_connlcm.disconnect()
        return False

    def get_netact_link_info(self, netact_index=None):
        self._get_netact_username_password(netact_index)
        return self.netactlink.strip()

    def get_netact_timezone(self, netact_index=None):
        self._get_netact_username_password(netact_index)
        try:
            ssh_conn = cli()
            myprompt = r"\[omc@\S+\s\S+\]\$"
            ssh_conn.connect_to(self.masterip, self.username, self.password, prompt=myprompt)
            gettimezonecommand = "date +%z"
            out = ssh_conn.execute(gettimezonecommand)
            logger.info('command return {0}'.format(out))
            netacttimezone = re.findall(r'[+-].{4}', out)
            logger.info('Netact time zone {0}'.format(netacttimezone))
            timezonestring = ''.join(netacttimezone)
            return timezonestring
        except Exception as e:
            logger.info("To get the Netact time zone error")
            logger.error(e)
        finally:
            ssh_conn.disconnect()
        return None

    def get_lcm_harbor_password(self, netact_index=None):
        self._get_netact_username_password(netact_index)
        try:
            ssh_conn = cli()
            myprompt = r"\[omc@\S+\s\S+\]\$"
            ssh_conn.connect_to(self.masterip, self.username, self.password, prompt=myprompt)
            gettlcmharborpwcommand = "/opt/nokia/oss/bin/syscredacc.sh -user ccradmin -type DB -instance CCR"
            out = ssh_conn.execute(gettlcmharborpwcommand)
            logger.info('command return {0}'.format(out))
            out = out.replace('\r\n', ',')
            outlist = out.split(',')
            harborpassword = outlist[1]
            return harborpassword.strip()
        except Exception as e:
            logger.info("To get the Netact LCM Harbor password for ccradmin error")
            logger.error(e)
        finally:
            ssh_conn.disconnect()
        return None
